import { Context, Effect, Layer } from "effect"

interface RetentionSettings {
  readonly maxAgeDays: number
  readonly batchSize: number
}

export class RetentionPolicy extends Context.Reference<RetentionPolicy>()(
  "archive/RetentionPolicy",
  {
    defaultValue: (): RetentionSettings => ({
      maxAgeDays: 30,
      batchSize: 100
    })
  }
) {}

export interface ArchivedDocument {
  readonly id: string
  readonly archivedAt: number
  readonly legalHold: boolean
}

export const planCleanup = (
  documents: ReadonlyArray<ArchivedDocument>,
  now: number
) =>
  Effect.gen(function*() {
    const policy = yield* RetentionPolicy
    const cutoff = now - policy.maxAgeDays * 86_400_000

    return documents
      .filter((document) => !document.legalHold && document.archivedAt < cutoff)
      .slice(0, policy.batchSize)
      .map((document) => document.id)
  })

export const ProductionRetention = Layer.succeed(RetentionPolicy, {
  maxAgeDays: 90,
  batchSize: 500
})

export const planProductionCleanup = (
  documents: ReadonlyArray<ArchivedDocument>,
  now: number
) => planCleanup(documents, now).pipe(Effect.provide(ProductionRetention))

